/**
 * marked.js CDN 로더
 * 브라우저: CDN에서 로드 (인터넷 필요)
 * APK 빌드 시: npm run bundle 또는 CDN URL을 index.html에서 직접 사용
 *
 * 실제 배포 전 https://cdn.jsdelivr.net/npm/marked/marked.min.js 를
 * 다운로드해서 이 파일을 교체하거나 index.html에 CDN 태그를 추가하세요.
 */
(function() {
  if (typeof marked !== 'undefined') return;

  // 런타임에 CDN 로드 시도
  const script = document.createElement('script');
  script.src = 'https://cdn.jsdelivr.net/npm/marked@12/marked.min.js';
  script.async = false;
  document.head.appendChild(script);
})();
